/**
 * Reproducible, source-preserving asset packer for PI Regulatory R70G.
 * The 17 feature sources remain editable individually; generated files are derived.
 * Usage: node scripts/pi-build-regulatory-assets.mjs [--check|--metrics]
 */
import {readFileSync, writeFileSync} from 'node:fs'
import {resolve, dirname} from 'node:path'
import {fileURLToPath} from 'node:url'

const dir = resolve(dirname(fileURLToPath(import.meta.url)), '../laravel/public')
const js = [
  'regulatory-laravel-r70g.js', 'regulatory-change-trace-r72.js',
  'regulatory-genealogy-r74.js', 'planning-lineage-r70j.js',
  'planning-program-r70k.js', 'normative-root-r70l.js',
  'regulatory-discovery-r70o.js', 'regulatory-ancestry-r70r.js',
  'regulatory-review-r75.js',
]
const css = [
  'regulatory-r69e.css', 'regulatory-trace-r70a.css',
  'regulatory-scope-r70d.css', 'regulatory-laravel-r70g.css',
  'regulatory-change-trace-r72.css', 'regulatory-genealogy-r74.css',
  'planning-lineage-r70j.css', 'regulatory-review-r75.css',
  'pi-design-tokens.css', 'pi-pxt-regulatory.css',
]
const outputs = [
  {names: js, name:'regulatory-workbench-r87.bundle.js', type:'js'},
  {names: css, name:'regulatory-workbench-r87.bundle.css', type:'css'},
]
const args = new Set(process.argv.slice(2))
if ([...args].some(arg => !['--check','--metrics'].includes(arg))) {
  throw new Error('Unknown argument')
}
// Git Windows checkouts may convert LF to CRLF; canonicalize only line endings.
const canonical = text => text.replace(/\r\n/g, '\n')
const read = name => canonical(readFileSync(resolve(dir,name), 'utf8'))
const banner = '/* Generated by scripts/pi-build-regulatory-assets.mjs. DO NOT EDIT. */\n'

function generate(bundle) {
  return banner + bundle.names.map(name => {
    const content = read(name).trimEnd()
    if (bundle.type === 'js') {
      return '/* BEGIN '+name+' */\n'+content+'\n;\n/* END '+name+' */\n'
    }
    return '/* BEGIN '+name+' */\n'+content+'\n/* END '+name+' */\n'
  }).join('')
}

let inputBytes = 0
let generatedBytes = 0
for (const bundle of outputs) {
  const target = resolve(dir,bundle.name)
  const built = generate(bundle)
  generatedBytes += Buffer.byteLength(built)
  inputBytes += bundle.names.reduce((n,name)=>n+Buffer.byteLength(read(name)),0)
  if (args.has('--check') || args.has('--metrics')) {
    if (canonical(readFileSync(target,'utf8')) !== built) {
      throw new Error('BUNDLE_DRIFT '+bundle.name)
    }
  } else {
    writeFileSync(target,built)
  }
}
const page = read('regulatory-laravel-r70g.html')
const scripts = (page.match(/<script\b[^>]*\bsrc="/g) || []).length
const styles = (page.match(/<link\b[^>]*rel="stylesheet"/g) || []).length
if (scripts !== 3 || styles !== 3
    || !page.includes('src="./regulatory-workbench-r87.bundle.js?v=r87a"')
    || !page.includes('href="./regulatory-workbench-r87.bundle.css?v=r87a"')
    || js.some(name => page.includes('src="./'+name))
    || css.some(name => page.includes('href="./'+name))) {
  throw new Error('R87_HTML_ASSET_REFERENCES_UNEXPECTED')
}
const metrics = {
  page:'regulatory-laravel-r70g.html',
  direct_static_asset_refs_before:21,
  direct_static_asset_refs_after:scripts+styles,
  direct_static_ref_reduction_percent:71.43,
  feature_source_uncompressed_bytes:inputBytes,
  feature_bundle_uncompressed_bytes:generatedBytes,
  network_timing:'NOT_MEASURED',
  browser_acceptance:'NOT_RUN',
  production_admission:'DENIED',
}
console.log(args.has('--metrics') ? JSON.stringify(metrics,null,2)
  : 'PI_R87_BUNDLE='+(args.has('--check')?'CHECK_PASS':'GENERATED')+'; STATIC_REFS=21->6')
